from typing import List
from wordle.types import Feedback

def score_guess(guess: str, target: str) -> List[Feedback]:
    feedback = [Feedback.MISS] * 5
    _mark_hits(guess, target, feedback)
    _mark_presents(guess, target, feedback)
    return feedback

def _count_letters(word: str) -> dict[str, int]:
    counts = {}
    for letter in word.lower():
        if letter in counts:
            counts[letter] += 1
        else:
            counts[letter] = 1
    return counts

def _mark_hits(guess: str, target: str, feedback: List[Feedback]) -> None:
    for i, (g_letter, t_letter) in enumerate(zip(guess, target)):
        if g_letter.lower() == t_letter.lower():
            feedback[i] = Feedback.HIT

def _mark_presents(guess: str, target: str, feedback: List[Feedback]) -> None:
    guess_counts = _count_letters(guess)
    target_counts = _count_letters(target)
    for i, g_letter in enumerate(guess):
        if feedback[i] != Feedback.HIT:
            g_letter_lower = g_letter.lower()
            if g_letter_lower in target_counts and target_counts[g_letter_lower] > 0 and guess_counts[g_letter_lower] > 0:
                feedback[i] = Feedback.PRESENT
                target_counts[g_letter_lower] -= 1
